    {ls_data, <<"cake.laws.prompt_drivers::type::SelfAskStep::FinalAnswer">>, [Value]};
to_dynamic_self_ask_step(
    #{'__struct__' := 'Elixir.LawSpec.Data.SelfAskStepFollowUp', value := Value}
